impl State {
    fn new() -> State {
        State {
            types_name: 0,
            index_name: 0,
            button_name: 0,
            size_is_number: false,
            shared_extra: 1,
            own_extra: 1,
            button_via_index: true,
            fancy_wraps_card: false,
            local_extra: 1,
            card_label_is_number: false,
            toggle_exported: true,
            button_exported: true,
            exists: [true; 7],
            broken: [false; 7],
        }
    }

    fn render(&self, file: File) -> String {
        let members = |prefix: &str, n: usize| -> String { (0..n).map(|i| format!("{prefix}{i}?: string; ")).collect() };
        let mut source = match file {
            File::Types => format!(
                "export interface Shared{} {{ size?: {}; {}}}\nexport type Tone = 'a' | 'b';\n",
                self.types_name,
                if self.size_is_number { "number" } else { "string" },
                members("m", self.shared_extra),
            ),
            File::Index => format!("export type {{ Shared{0} }} from './types';\nexport type {{ Tone }} from './types';\n", self.index_name),
